const input = $input.first().json;
const body = input.body ?? {};

function normalizarTelefonoArgentina(numero) {
  if (numero === null || numero === undefined) {
    return null;
  }

  let limpio = String(numero).replace(/\D/g, '');

  if (!limpio) {
    return null;
  }

  // Quitar prefijo internacional 00
  if (limpio.startsWith('00')) {
    limpio = limpio.slice(2);
  }

  // Ya viene como 549 + 10 dígitos
  if (/^549\d{10}$/.test(limpio)) {
    return limpio;
  }

  // Viene como 54 + 10 dígitos, sin el 9 de celular
  if (/^54\d{10}$/.test(limpio)) {
    return `549${limpio.slice(2)}`;
  }

  // Quitar el cero nacional inicial
  if (limpio.startsWith('0')) {
    limpio = limpio.slice(1);
  }

  // Número nacional argentino: área + teléfono = 10 dígitos
  if (/^\d{10}$/.test(limpio)) {
    return `549${limpio}`;
  }

  return null;
}

const telefonoCelular = body.pilot_cellphone ?? null;
const telefonoFijo = body.pilot_phone ?? null;

const celularNormalizado =
  normalizarTelefonoArgentina(telefonoCelular);

const telefonoNormalizado =
  normalizarTelefonoArgentina(telefonoFijo);

const whatsapp =
  celularNormalizado ??
  telefonoNormalizado ??
  null;

let campoUtilizado = null;
let original = null;

if (celularNormalizado) {
  campoUtilizado = 'pilot_cellphone';
  original = telefonoCelular;
} else if (telefonoNormalizado) {
  campoUtilizado = 'pilot_phone';
  original = telefonoFijo;
}

return [
  {
    json: {
      whatsapp,
      valido: whatsapp !== null,
      original,
      campo_utilizado: campoUtilizado,
      telefonos_recibidos: {
        pilot_cellphone: telefonoCelular,
        pilot_phone: telefonoFijo,
      },
      telefonos_normalizados: {
        pilot_cellphone: celularNormalizado,
        pilot_phone: telefonoNormalizado,
      },
    },
  },
];

// ======================================================
// Webhook → preparar disparo restringido BAIC Central
// ======================================================
const root = $input.first()?.json || {};
const body = root.body || root;

// ======================================================
// DATOS DEL CLIENTE
// ======================================================
const firstname =
  String(body.pilot_firstname || '').trim() ||
  [body.pilot_firstname, body.pilot_lastname]
    .filter((v) => v != null && String(v).trim() !== '')
    .map((v) => String(v).trim())
    .join(' ') ||
  'Cliente';

const negocio =
  String(body.pilot_negocio || '').trim();

const producto =
  String(body.pilot_product_of_interest || '').trim();

// ======================================================
// TELÉFONO
// ======================================================
let telefono =
  body.pilot_cellphone ||
  body.pilot_phone ||
  null;

// ======================================================
// NORMALIZADOR ARGENTINA
// ======================================================
function normalizarTelefonoArgentina(numero) {
  if (!numero) return null;

  let limpio = String(numero).replace(/\D/g, '');

  if (limpio.startsWith('549') && limpio.length === 13) {
    return limpio;
  }

  if (limpio.startsWith('54') && limpio.length === 12) {
    return '549' + limpio.slice(2);
  }

  if (limpio.startsWith('0')) {
    limpio = limpio.slice(1);
  }

  if (limpio.length === 10) {
    return '549' + limpio;
  }

  return null;
}

const whatsapp = normalizarTelefonoArgentina(telefono);

// ======================================================
// NORMALIZAR NEGOCIO / PRODUCTO
// ======================================================
const negocioNorm = negocio
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toUpperCase()
  .replace(/\s+/g, ' ')
  .trim();

const productoNorm = producto
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toUpperCase()
  .replace(/\s+/g, ' ')
  .trim();

// ======================================================
// VALIDAR QUE SEA BAIC
// ======================================================
const esBaic =
  negocioNorm.includes('BAIC') ||
  productoNorm.includes('BAIC');

// ======================================================
// CONSTANTES TWILIO BAIC CENTRAL
// ======================================================
const ACCOUNT_SID = 'TWILIO_SID_OCULTO';

const MESSAGING_SERVICE_SID =
  'MG085b57d6e13cc5af223ab80477b9e12e';

const FROM_PHONE =
  'whatsapp:+5491180243654';

const CONTENT_SID =
  'HX92c58c83bee1be554198e4b2eff0e641';

const TWILIO_CREDENTIAL_REF =
  'BAIC CENTRAL TWILIO';

// ======================================================
// CONTENT VARIABLES
// ======================================================
const contentVariablesObj = {
  '1': firstname,
  '2': 'WhatsApp-Image-2026-05-14-at-17.32.45_20260514_173441.jpeg',
  '3': '123123123'
};

const contentVariables =
  JSON.stringify(contentVariablesObj);

// ======================================================
// VALIDACIONES
// ======================================================
const telefonoValido =
  whatsapp !== null;

const datosClienteValidos =
  firstname !== '' &&
  firstname !== 'Cliente';

const negocioValido =
  esBaic;

const templateValido =
  CONTENT_SID !== '';

const valido =
  telefonoValido &&
  datosClienteValidos &&
  negocioValido &&
  templateValido;

// ======================================================
// SALIDA
// ======================================================
return [
  {
    json: {
      valido,

      telefonoValido,
      datosClienteValidos,
      negocioValido,
      templateValido,

      whatsapp,
      to_phone: whatsapp,

      firstname,

      negocio,
      negocioNorm,

      producto,
      productoNorm,

      account_sid: ACCOUNT_SID,
      messaging_service_sid: MESSAGING_SERVICE_SID,
      from_phone: FROM_PHONE,

      content_sid: CONTENT_SID,
      content_variables: contentVariables,

      original: telefono,

      twilio_credential_ref: TWILIO_CREDENTIAL_REF,

      source: 'n8n:baic-central-restricciones',

      payload_json: {
        firstname,
